import java.util.*;

class Solution {
  public int maxNumberOfAlloys(
      int n,
      int k,
      int budget,
      List<List<Integer>> composition,
      List<Integer> stock,
      List<Integer> cost) {
    long answer = 0;
    for (List<Integer> recipe : composition) {
      long lo = 0, hi = 2_000_000_001L;
      while (lo < hi) {
        long mid = (lo + hi + 1) / 2, spent = 0;
        for (int i = 0; i < n; i++) {
          long need = mid * recipe.get(i) - stock.get(i);
          if (need > 0) {
            spent += need * cost.get(i);
            if (spent > budget) break;
          }
        }
        if (spent <= budget) lo = mid;
        else hi = mid - 1;
      }
      answer = Math.max(answer, lo);
    }
    return (int) answer;
  }
}
